import { useState, useEffect, useRef } from "react";
import { useOpcUa } from '../hooks/useOpcUa';
import api from '../api';

const C = {
    bg: '#0d1117', panel: '#161b22', panelBd: '#30363d',
    text: '#e6edf3', dim: '#7d8590', accent: '#58a6ff',
    green: '#3fb950', red: '#f85149', yellow: '#d29922',
    water: '#2980b9', roller: '#3a3f47', rollerBd: '#555d68', display: '#010409',
};
const ZONE_FILL = ['#7f1d1d', '#7c2d12', '#713f12', '#3b3009'];
const ZONE_STROKE = ['#dc2626', '#ea580c', '#ca8a04', '#a16207'];
const ZONE_LABEL = ['#fca5a5', '#fdba74', '#fde68a', '#fef08a'];

const statusColor = s => ({
    'В работе': '#3fb950', 'На рольганге': '#58a6ff',
    'Завершён': '#7d8590', 'Ожидание': '#d29922', 'Создан': '#8b949e',
}[s] ?? '#f85149');

const toBool = v => v === true || v === 1 || v === '1' || v === 'true';
const toStr = v => (v === null || v === undefined) ? '—' : String(v);

const valveState = v => {
    if (v === 1 || v === '1' || v === true) return 1;
    if (v === 6 || v === '6') return 6;
    return 0;
};

// ── Primitives ─────────────────────────────────────────────────────────────
const Led = ({ on, color = '#3fb950', size = 10 }) => (
    <span style={{
        display: 'inline-block', width: size, height: size, borderRadius: '50%',
        background: on ? color : '#252a30',
        boxShadow: on ? `0 0 5px ${color}` : 'none', flexShrink: 0,
    }} />
);

const Seg = ({ value, unit = '', width = 70 }) => (
    <div style={{
        background: C.display, border: '1px solid #1c6ca8', borderRadius: 3,
        padding: '2px 5px', minWidth: width, textAlign: 'right',
        display: 'inline-flex', alignItems: 'center', justifyContent: 'flex-end', gap: 3,
    }}>
        <span style={{ fontFamily: 'monospace', fontSize: 13, color: '#4fc3f7', fontWeight: 700 }}>{value}</span>
        {unit && <span style={{ fontSize: 14, color: C.dim }}>{unit}</span>}
    </div>
);

// ── SVG LED для клапана (внутри зоны ЗАКАЛКА) ──
const ValveLed = ({ cx, cy, state, r = 4.5 }) => {
    const color = state === 1 ? C.green : state === 6 ? C.red : '#252a30';
    const stroke = state === 6 ? C.red : state === 1 ? '#2ea043' : '#444';
    return (
        <g>
            {state === 1 && (
                <circle cx={cx} cy={cy} r={r + 2.5} fill="none" stroke={C.green} strokeWidth={0.6} opacity={0.4} />
            )}
            {state === 6 && (
                <circle cx={cx} cy={cy} r={r + 2.5} fill="none" stroke={C.red} strokeWidth={0.6} opacity={0.5} />
            )}
            <circle cx={cx} cy={cy} r={r} fill={color} stroke={stroke} strokeWidth={0.8} />
            {state === 6 && (
                <text x={cx} y={cy + 2.5} textAnchor="middle" fill="#fff" fontSize={6} fontWeight={700}>!</text>
            )}
        </g>
    );
};

// ── SVG helpers ─────────────────────────────────────────────────────────────
const Rollers = ({ x, y, count, w = 16, gap = 5, h = 30 }) => (
    <>{Array.from({ length: count }).map((_, i) => (
        <g key={i}>
            <rect x={x + i * (w + gap)} y={y} width={w} height={h} rx={w / 2}
                fill={C.roller} stroke={C.rollerBd} strokeWidth={1} />
            <circle cx={x + i * (w + gap) + w / 2} cy={y + h / 2} r={3}
                fill="none" stroke={C.rollerBd} strokeWidth={1.5} />
        </g>
    ))}</>
);

const SheetRect = ({ x, y, w, h = 16, label, color }) => (
    <g>
        <rect x={x} y={y} width={w} height={h} rx={2}
            fill={color} stroke="#8b949e" strokeWidth={1} opacity={0.92} />
        {label && <text x={x + w / 2} y={y + h / 2 + 3.5} textAnchor="middle"
            fill="#e6edf3" fontSize={8} fontFamily="monospace" fontWeight={600}>{label}</text>}
    </g>
);

const Nozzles9 = ({ x, y, active, side }) => (
    <>{Array.from({ length: 9 }).map((_, i) => {
        const cx = x + i * 13 + 6;
        const tipY = side === 'top' ? y + 10 : y - 10;
        return (
            <g key={i}>
                <polygon
                    points={`${cx - 4},${y} ${cx + 4},${y} ${cx},${tipY}`}
                    fill={active ? C.water : '#252a30'}
                    stroke={active ? '#60a5fa' : '#333'} strokeWidth={0.5}
                />
                {active && <line x1={cx} y1={tipY} x2={cx}
                    y2={side === 'top' ? tipY + 9 : tipY - 9}
                    stroke={C.water} strokeWidth={1.5} strokeDasharray="2,2" opacity={0.7} />}
            </g>
        );
    })}</>
);

// ── Main ────────────────────────────────────────────────────────────────────
export default function QuenchingHMI() {
    const [time, setTime] = useState(new Date());
    const [selSheetId, setSelSheet] = useState(null);
    const [inputSheet, setInputSheet] = useState(null);
    const [coolT, setCoolT] = useState(19.1);
    const [running, setRunning] = useState(true);
    const [loading, setLoading] = useState(true);
    const [sheetsLoading, setSheetsLoading] = useState(false);
    const [error, setError] = useState(null);
    const [selectedPlan, setSelectedPlan] = useState(null);
    const [plans, setPlans] = useState([]);
    const [submitting, setsubmitting] = useState(false);

    const [liveData, setLiveData] = useState({
        entry: null,
        furnace: [null, null, null, null],
        quench: null,
        cool: null,
        output: null,
        arrows: {
            toFurnace: false,
            zones: [false, false, false, false],
        },
    });

    const { values, connected, write } = useOpcUa([
        'PLC210.T_F1_MedAct', 'PLC210.T_F2_MedAct', 'PLC210.T_F3_MedAct', 'PLC210.T_F4_MedAct',
        'PLC210.E1_Ocp', 'PLC210.E1_Melt', 'PLC210.E1_PartNo', 'PLC210.E1_Pack', 'PLC210.E1_Sheet',
        'PLC210.F1_ZoneOccup', 'PLC210.F1_InArrow', 'PLC210.F1_OutArrow', 'PLC210.F1_Melt', 'PLC210.F1_PartNo', 'PLC210.F1_Pack', 'PLC210.F1_Sheet',
        'PLC210.F2_ZoneOccup', 'PLC210.F2_OutArrow', 'PLC210.F2_Melt', 'PLC210.F2_PartNo', 'PLC210.F2_Pack', 'PLC210.F2_Sheet',
        'PLC210.F3_ZoneOccup', 'PLC210.F3_OutArrow', 'PLC210.F3_Melt', 'PLC210.F3_PartNo', 'PLC210.F3_Pack', 'PLC210.F3_Sheet',
        'PLC210.F4_ZoneOccup', 'PLC210.F4_OutArrow', 'PLC210.F4_Melt', 'PLC210.F4_PartNo', 'PLC210.F4_Pack', 'PLC210.F4_Sheet', 'PLC210.F4_AlloyCodeText', 'PLC210.F4_Thikness',
        'PLC210.X1_ZoneOccup', 'PLC210.X1_Melt', 'PLC210.X1_PartNo', 'PLC210.X1_Pack', 'PLC210.X1_Sheet',
        'PLC210.X2_ZoneOccup', 'PLC210.X2_Melt', 'PLC210.X2_PartNo', 'PLC210.X2_Pack', 'PLC210.X2_Sheet',
        'PLC210.ModeLen', 'PLC210.TmpSet', 'PLC210.X1_UnLoadSpeed', 'PLC210.F4_UnLoadSpeed',
        'PLC210.Valave_1x1_MnAt', 'PLC210.Valave_1x2_MnAt', 'PLC210.Valave_1x3_MnAt', 'PLC210.Valave_1x4_MnAt', 'PLC210.Valave_1x5_MnAt',
        'PLC210.Valave_1x6_MnAt', 'PLC210.Valave_1x7_MnAt', 'PLC210.Valave_1x8_MnAt', 'PLC210.Valave_1x9_MnAt',
        'PLC210.Valave_2x1_MnAt', 'PLC210.Valave_2x2_MnAt', 'PLC210.Valave_2x3_MnAt', 'PLC210.Valave_2x4_MnAt', 'PLC210.Valave_2x5_MnAt',
        'PLC210.Valave_2x6_MnAt', 'PLC210.Valave_2x7_MnAt', 'PLC210.Valave_2x8_MnAt', 'PLC210.Valave_2x9_MnAt',
        // Теги для удаления листов из зон
        'PLC210.DelPlate_E1',
        'PLC210.DelPlate_F1',
        'PLC210.DelPlate_F2',
        'PLC210.DelPlate_F3',
        'PLC210.DelPlate_F4',
        'PLC210.DelPlate_X1',
        'PLC210.DelPlate_X2',
    ]);

    // Храним предыдущее состояние тегов удаления для отслеживания момента срабатывания (rising edge)
    const lastDeleteState = useRef({
        E1: false, F1: false, F2: false, F3: false, F4: false, X1: false, X2: false
    });

    // Вспомогательная функция: преобразует тег зоны (E1, F1) в текстовую локацию из таблицы ('Вход', 'Зона 1')
    const getLocFromZoneTag = (zoneTag) => {
        if (zoneTag === 'E1') return 'Вход';
        if (zoneTag === 'F1') return 'Зона 1';
        if (zoneTag === 'F2') return 'Зона 2';
        if (zoneTag === 'F3') return 'Зона 3';
        if (zoneTag === 'F4') return 'Зона 4';
        if (zoneTag === 'X1') return 'Закалка'; // Или 'Охл.', в зависимости от вашей логики
        if (zoneTag === 'X2') return 'Выдача';
        return null;
    };
    useEffect(() => {
        const makeSheet = (prefix) => {
            const fullPrefix = `PLC210.${prefix}`;
            const occ = toBool(values[`${fullPrefix}_ZoneOccup`]?.value ?? values[`${fullPrefix}_Ocp`]?.value);
            if (!occ) return null;
            return {
                melt: toStr(values[`${fullPrefix}_Melt`]?.value),
                sheet: toStr(values[`${fullPrefix}_Sheet`]?.value),
                pack: toStr(values[`${fullPrefix}_Pack`]?.value),
                batch: toStr(values[`${fullPrefix}_PartNo`]?.value),
                grade: toStr(values[`${fullPrefix}_AlloyCodeText`]?.value),
                thick: toStr(values[`${fullPrefix}_Thikness`]?.value),
            };
        };

        const entryOcc = toBool(values['PLC210.E1_Ocp']?.value);
        const entrySheet = entryOcc ? {
            melt: toStr(values['PLC210.E1_Melt']?.value),
            sheet: toStr(values['PLC210.E1_Sheet']?.value),
            pack: toStr(values['PLC210.E1_Pack']?.value),
            batch: toStr(values['PLC210.E1_PartNo']?.value),
        } : null;

        const x1Sheet = makeSheet('X1');

        setLiveData({
            entry: entrySheet,
            furnace: [1, 2, 3, 4].map(i => makeSheet(`F${i}`)),
            quench: x1Sheet,
            cool: x1Sheet,
            output: makeSheet('X2'),
            arrows: {
                toFurnace: toBool(values['PLC210.F1_InArrow']?.value),
                zones: [1, 2, 3, 4].map(i => toBool(values[`PLC210.F${i}_OutArrow`]?.value)),
            },
        });
    }, [values]);

    const realTemps = [
        Math.round(values['PLC210.T_F1_MedAct']?.value ?? 0),
        Math.round(values['PLC210.T_F2_MedAct']?.value ?? 0),
        Math.round(values['PLC210.T_F3_MedAct']?.value ?? 0),
        Math.round(values['PLC210.T_F4_MedAct']?.value ?? 0),
    ];

    // ── ЖИВЫЕ ПАРАМЕТРЫ ──
    const rawSpeed = values['PLC210.F4_UnLoadSpeed']?.value;
    const rawTmpSet = values['PLC210.TmpSet']?.value;
    const rawModeLen = values['PLC210.ModeLen']?.value;

    const speedDisplay = (rawSpeed != null && !isNaN(rawSpeed)) ? Number(rawSpeed) : '—';
    const tempSetDisplay = (rawTmpSet != null && !isNaN(rawTmpSet)) ? Number(rawTmpSet).toFixed(1) : '—';
    const lengthDisplay = rawModeLen === 1 || rawModeLen === '1' ? '6'
        : rawModeLen === 0 || rawModeLen === '0' ? '3'
            : '—';

    // ── СОСТОЯНИЯ 18 КЛАПАНОВ ──
    // ИСПРАВЛЕНО: добавлен символ _ вместо пустоты (,i) =>
    const topValves = Array.from({ length: 9 }, (_, i) => valveState(values[`PLC210.Valave_1x${i + 1}_MnAt`]?.value));
    const bottomValves = Array.from({ length: 9 }, (_, i) => valveState(values[`PLC210.Valave_2x${i + 1}_MnAt`]?.value));

    const setZoneTemp = async (zone, temp) => {
        const ok = await write(`z${zone}_setpoint`, temp);
        console.log('Write result:', ok);
    };

    const fetchPlans = async () => {
        try {
            setLoading(true);
            const response = await api.get('/quenchinghmi/plans');
            setPlans(response.data);
            setError(null);
        } catch (err) {
            console.error('Ошибка при загрузке планов:', err);
            setError(err.message);
            setPlans([]);
        } finally {
            setLoading(false);
        }
    };

    const fetchPlanSheets = async (planId) => {
        try {
            setSheetsLoading(true);
            const response = await api.get(`/quenchinghmi/plans/${planId}/sheets`);
            if (response.status < 200 || response.status >= 300)
                throw new Error(`Ошибка загрузки листов плана ${planId}: ${response.status}`);
            const basePlan = plans.find(p => p.id === planId);
            setSelectedPlan({ ...basePlan, sheets: response.data });
        } catch (err) {
            console.error('Ошибка при загрузке листов плана:', err);
            setError(err.message);
            setSelectedPlan(null);
        } finally {
            setSheetsLoading(false);
        }
    };

    useEffect(() => { fetchPlans(); }, []);
    const [lastAddedSheetId, setLastAddedSheetId] = useState(null);
    const [lastAddedTime, setLastAddedTime] = useState(0);


    const addToConveyor = async () => {
        if (!canAdd || submitting) return;
        setsubmitting(true);
        try {
            const modelen = selSheet.length > 3 ? 1 : 0;
            await api.post('/quenchinghmi/write-entry', {
                EntrPlateData_Melt: Number(selSheet.melt) || 0,
                EntrPlateData_PartNo: Number(selSheet.batch) || 0,
                EntrPlateData_Pack: Number(selSheet.pack) || 0,
                EntrPlateData_Sheet: Number(selSheet.sheet) || 0,
                UniqueId: selSheet.uniqueId || "",
                EntrPlateData_AlloyCodeText: selSheet.grade ? String(selSheet.grade) : "",
                EntrPlateData_ThiknessText: selSheet.thick ? String(selSheet.thick) : "",
                EntrPlateData_SubSheet: "",
                ModeLen: modelen,
                EntrPlateData_SheetInPack: 0,
                EntrPlateData_Slab: Number(selSheet.slab) || 0, 
                EntrPlateData_InsertToE1: true,
            });

            setInputSheet(selSheet);

            // Сохраняем ID и время подачи
            setLastAddedSheetId(selSheetId);
            setLastAddedTime(Date.now());

            setSelectedPlan(prev => ({
                ...prev,
                sheets: prev.sheets.map(s =>
                    s.id === selSheetId ? { ...s, status: 'На рольганге', loc: 'Вход' } : s
                ),
            }));
            setSelSheet(null);
        } catch (err) {
            setError(`Ошибка подачи листа: ${err.response?.data?.message || err.message}`);
            console.error('Детали ошибки:', err.response?.data);
        } finally {
            setsubmitting(false);
        }
    };

    const deleteFromZone = async (sheetId, zone) => {
        if (!sheetId || !zone) return;

        const sheet = planSheets.find(s => s.id === sheetId);
        if (!sheet) return;

        const sheetLabel = `${sheet.melt}/${sheet.sheet}`;
        if (!window.confirm(
            `Удалить лист ${sheetLabel} из зоны ${zone}?\n\nЛист вернется в статус "Ожидание"`
        )) return;

        try {
            // Вызываем backend endpoint
            const response = await api.post('/quenchinghmi/delete-from-zone', {
                UniqueId: sheet.uniqueId,
                Zone: zone,
            });

            console.log('Delete result:', response.data);

            // Обновляем статус листа в плане
            setSelectedPlan(prev => ({
                ...prev,
                sheets: prev.sheets.map(s =>
                    s.id === sheetId
                        ? { ...s, status: 'Ожидание', loc: null }
                        : s
                ),
            }));

            // Если удаляем лист с входного рольганга, очищаем inputSheet
            if (zone === 'E1' && inputSheet?.id === sheetId) {
                setInputSheet(null);
            }
        } catch (err) {
            setError(`Ошибка удаления листа: ${err.response?.data?.message || err.message}`);
            console.error('Детали ошибки:', err.response?.data);
        }
    };

    // Вспомогательная функция: возвращает массив допустимых локаций для тега зоны
    const getValidLocsForZone = (zoneTag) => {
        if (zoneTag === 'E1') return ['Вход'];
        if (zoneTag === 'F1') return ['Зона 1'];
        if (zoneTag === 'F2') return ['Зона 2'];
        if (zoneTag === 'F3') return ['Зона 3'];
        if (zoneTag === 'F4') return ['Зона 4'];
        if (zoneTag === 'X1') return ['Закалка', 'Охл.']; // Поддержка обоих вариантов
        if (zoneTag === 'X2') return ['Выдача'];
        return [];
    };
    const getZoneTag = (loc) => {
        if (loc === 'Вход') return 'E1';
        if (loc === 'Закалка') return 'X1';
        if (loc === 'Охл.') return 'X1';
        if (loc === 'Выдача') return 'X2';
        if (loc && loc.startsWith('Зона ')) return loc.replace('Зона ', 'F');
        return null;
    };

    useEffect(() => {
        if (!selectedPlan?.sheets) return;

        let hasChanges = false;
        const updatedSheets = [...selectedPlan.sheets];
        let newInputSheet = inputSheet;

        // ── 1. ПРОАКТИВНАЯ СИНХРОНИЗАЦИЯ ВХОДНОГО РОЛЬГАНГА (E1) ──
        if (liveData.entry) {
            // ПЛК говорит, что на входе есть лист. Ищем его в нашем плане по уникальным данным.
            // Это исправляет ситуацию, когда лист подали с ДРУГОГО HMI.
            const sheetIndex = updatedSheets.findIndex(s =>
                s.melt === liveData.entry.melt &&
                s.batch === liveData.entry.batch &&
                s.pack === liveData.entry.pack &&
                s.sheet === liveData.entry.sheet
            );

            if (sheetIndex !== -1) {
                const currentSheet = updatedSheets[sheetIndex];
                // Принудительно ставим правильный статус и локацию, чтобы появилась кнопка "Удалить"
                if (currentSheet.status !== 'На рольганге' || currentSheet.loc !== 'Вход') {
                    updatedSheets[sheetIndex] = {
                        ...currentSheet,
                        status: 'На рольганге',
                        loc: 'Вход'
                    };
                    hasChanges = true;
                }
                // Если этот лист не отображается как поданный в локальном состоянии, исправляем это
                if (!inputSheet || inputSheet.id !== currentSheet.id) {
                    newInputSheet = currentSheet;
                }
            }
        } else {
            // ПЛК говорит, что входной рольганг ПУСТ.
            // Ищем и очищаем любые "застрявшие" листы, которые могли зависнуть из-за рассинхрона.
            const stuckIndex = updatedSheets.findIndex(s => s.loc === 'Вход' && (s.status === 'На рольганге' || s.status === 'В работе'));
            if (stuckIndex !== -1) {
                updatedSheets[stuckIndex] = {
                    ...updatedSheets[stuckIndex],
                    status: 'Ожидание',
                    loc: null
                };
                hasChanges = true;

                // Если "зависший" лист был в inputSheet, очищаем его, чтобы разблокировать кнопку "Подать"
                if (inputSheet && inputSheet.id === updatedSheets[stuckIndex].id) {
                    newInputSheet = null;
                }
            }
        }

        // ── 2. РЕАКТИВНАЯ ОБРАБОТКА КОМАНД УДАЛЕНИЯ (RISING EDGE) ──
        const deleteTags = {
            E1: toBool(values['PLC210.DelPlate_E1']?.value),
            F1: toBool(values['PLC210.DelPlate_F1']?.value),
            F2: toBool(values['PLC210.DelPlate_F2']?.value),
            F3: toBool(values['PLC210.DelPlate_F3']?.value),
            F4: toBool(values['PLC210.DelPlate_F4']?.value),
            X1: toBool(values['PLC210.DelPlate_X1']?.value),
            X2: toBool(values['PLC210.DelPlate_X2']?.value),
        };

        for (const [zone, isTriggered] of Object.entries(deleteTags)) {
            const wasTriggered = lastDeleteState.current[zone];

            // Ловим момент срабатывания: было false, стало true
            if (isTriggered && !wasTriggered) {
                console.log(`[OPC-UA] Команда удаления из зоны: ${zone}`);

                let sheetIndex = -1;
                const validLocs = getValidLocsForZone(zone);

                if (zone === 'E1' && liveData.entry) {
                    // Для E1 приоритетно ищем по совпадению данных с ПЛК (максимальная надежность)
                    sheetIndex = updatedSheets.findIndex(s =>
                        s.melt === liveData.entry.melt &&
                        s.batch === liveData.entry.batch &&
                        s.pack === liveData.entry.pack &&
                        s.sheet === liveData.entry.sheet
                    );
                } else {
                    // Для остальных зон ищем по локации (с поддержкой массива локаций)
                    sheetIndex = updatedSheets.findIndex(
                        s => validLocs.includes(s.loc) && (s.status === 'На рольганге' || s.status === 'В работе')
                    );
                }

                if (sheetIndex !== -1) {
                    updatedSheets[sheetIndex] = {
                        ...updatedSheets[sheetIndex],
                        status: 'Ожидание',
                        loc: null
                    };
                    hasChanges = true;

                    if (zone === 'E1' && inputSheet?.id === updatedSheets[sheetIndex].id) {
                        newInputSheet = null;
                    }
                }
            }
            // Обновляем память о состоянии тега
            lastDeleteState.current[zone] = isTriggered;
        }

        // Применяем изменения, если они были
        if (hasChanges) {
            setSelectedPlan(prev => prev ? { ...prev, sheets: updatedSheets } : prev);
        }

        // Обновляем inputSheet только если он действительно изменился
        if (newInputSheet !== inputSheet) {
            setInputSheet(newInputSheet);
        }

    }, [values, selectedPlan, inputSheet, liveData.entry]); 

const [defectModal, setDefectModal] = useState({
    open: false, sheet: null, loading: false, error: null,
    reason: '', defectTypeId: null,
});
const [defectTypes, setDefectTypes] = useState([]);

useEffect(() => {
    api.get('/defects/types')
        .then(res => setDefectTypes(res.data))
        .catch(err => console.error('Ошибка загрузки типов брака:', err));
}, []);

const handleSheetClick = (zoneName, sheetData) => {
    if (!sheetData) return;
    openDefectModal({
        melt: sheetData.melt, batch: sheetData.batch,
        pack: sheetData.pack, sheet: sheetData.sheet, zone: zoneName,
    });
};

const openDefectModal = async (sheetInfo) => {
    setDefectModal({
        open: true, sheet: null, loading: true, error: null,
        reason: '', defectTypeId: null, detectedZone: sheetInfo.zone || 'X2',
    });
    try {
        const res = await api.get('/quenchinghmi/find-sheet', {
            params: {
                melt: sheetInfo.melt, batch: sheetInfo.batch,
                pack: sheetInfo.pack, sheet: sheetInfo.sheet,
            },
        });
        setDefectModal((prev) => ({ ...prev, sheet: res.data, loading: false }));
    } catch (err) {
        setDefectModal((prev) => ({
            ...prev, loading: false,
            error: `Лист не найден в БД: ${err.response?.data?.message || err.message}`,
        }));
    }
};

const closeDefectModal = () => {
    setDefectModal({
        open: false, sheet: null, loading: false, error: null,
        reason: '', defectTypeId: null, detectedZone: 'X2',
    });
};

const markAsDefect = async () => {
    if (!defectModal.sheet) return;
    const sheetLabel = `${defectModal.sheet.meltNumber}/${defectModal.sheet.sheetNumber}`;
    if (!window.confirm(
        `Подтвердите установку статуса "БРАК" для листа ${sheetLabel}?\n\nЗона: ${defectModal.detectedZone}\nПричина: ${defectModal.reason || 'Не указана'}`
    )) return;

    setDefectModal((prev) => ({ ...prev, loading: true, error: null }));
    try {
        await api.post('/defects', {
            matId: defectModal.sheet.matId,
            defectTypeId: defectModal.defectTypeId,
            description: defectModal.reason || 'Не указана',
            detectedAtZone: defectModal.detectedZone,
            severity: 2,
        });
        closeDefectModal();
        if (selectedPlan) fetchPlanSheets(selectedPlan.id);
    } catch (err) {
        setDefectModal((prev) => ({
            ...prev, loading: false,
            error: err.response?.data?.message || err.message,
        }));
    }
};

useEffect(() => {
    const id = setInterval(() => {
        setTime(new Date());
        setCoolT(t => Math.round((t + (Math.random() - 0.5) * 0.4) * 10) / 10);
    }, 10000);
    return () => clearInterval(id);
}, []);

const handleSelectPlan = (plan) => {
    setSelectedPlan(plan);
    fetchPlanSheets(plan.id);
    setSelSheet(null);
};

const allSheets = selectedPlan?.sheets ?? [];
const inLoc = loc => allSheets.find(s => s.loc === loc);
const planSheets = selectedPlan?.sheets ?? [];
const selSheet = planSheets.find(s => s.id === selSheetId);
const canAdd = !!selSheetId && selSheet?.status === 'Ожидание' && !inputSheet;

const zones = liveData.furnace.map((live, i) => live ?? inLoc(`Зона ${i + 1}`));
const qS = liveData.quench ?? inLoc('Закалка');
const cS = liveData.cool ?? inLoc('Охл.');
const svgEntry = liveData.entry ?? inputSheet;

const loadToFurnace = () => {
    if (!inputSheet) return;
    const free = ['Зона 1', 'Зона 2', 'Зона 3', 'Зона 4'].find(z => !inLoc(z));
    if (!free) return;
    setSelectedPlan(prev => ({
        ...prev,
        sheets: prev.sheets.map(s =>
            s.id === inputSheet.id ? { ...s, status: 'В работе', loc: free } : s
        ),
    }));
    setInputSheet(null);
};

const fmt = d => d.toTimeString().slice(0, 8);

const VW = 1000, VH = 230;
const rY = 110, rH = 30, rW = 16, rGap = 5;

const inX = 10, inN = 5;
const fX = inX + inN * (rW + rGap) + 22;
// ИСПРАВЛЕНО: добавлены знаки умножения *
const zW = 118, zGap = 2, furnW = 4 * zW + 3 * zGap;
const qX = fX + furnW + 20;
const qW = 126;
const outX = qX + qW + 20;
const outN = 6;
const finX = outX + outN * (rW + rGap) + 18;
const finN = 4;

const zoneX = i => fX + i * (zW + zGap);

return (
    <div style={{
        background: C.bg, color: C.text, fontFamily: "'Courier New',monospace",
        minHeight: '100vh', padding: 10, fontSize: 14, boxSizing: 'border-box',
    }}>

        {/* ══ TOP BAR ═══════════════════════════════════════════════════════ */}
        <div style={{
            display: 'flex', gap: 10, alignItems: 'center', flexWrap: 'nowrap',
            background: C.panel, border: `1px solid ${C.panelBd}`,
            borderRadius: 6, padding: '7px 12px', marginBottom: 8,
        }}>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 4, flexShrink: 0, minWidth: 155 }}>
                {[
                    { on: false, color: C.red, label: 'Аварийный останов' },
                    { on: false, color: C.red, label: 'Блокировка нагрева' },
                    { on: running, color: C.green, label: 'Готовность к запуску' },
                    { on: !!svgEntry, color: C.accent, label: 'Лист на рольганге' },
                ].map(({ on, color, label }) => (
                    <div key={label} style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                        <Led on={on} color={color} />
                        <span style={{ fontSize: 14, color: C.dim }}>{label}</span>
                    </div>
                ))}
            </div>

            <div style={{ width: 1, height: 48, background: C.panelBd, flexShrink: 0 }} />

            <div style={{ flexShrink: 0 }}>
                <div style={{ fontSize: 14, color: C.dim, letterSpacing: 1, marginBottom: 3 }}>ТЕМП. ЗОН</div>
                <div style={{ display: 'flex', gap: 5 }}>
                    {realTemps.map((t, i) => (
                        <div key={i} style={{ textAlign: 'center' }}>
                            <div style={{ fontSize: 14, color: ZONE_LABEL[i], marginBottom: 2 }}>З{i + 1}</div>
                            <Seg value={t} unit="°C" width={62} />
                        </div>
                    ))}
                </div>
            </div>

            <div style={{ width: 1, height: 48, background: C.panelBd, flexShrink: 0 }} />

            <div style={{ flexShrink: 0 }}>
                <div style={{ fontSize: 14, color: C.dim, letterSpacing: 1, marginBottom: 3 }}>ЛИСТ В ЗОНЕ 4</div>
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4,auto)', gap: '2px 8px', alignItems: 'center' }}>
                    {['Плавка', 'Партия', 'Пачка', 'Лист'].map(l => (
                        <span key={l} style={{ fontSize: 14, color: C.dim }}>{l}</span>
                    ))}
                    {[zones[3]?.melt || '──────', zones[3]?.batch || '───', zones[3]?.pack || '──', zones[3]?.sheet || '────'].map((v, i) => (
                        <Seg key={i} value={v} width={i === 0 ? 68 : 40} />
                    ))}
                </div>
            </div>

            <div style={{ width: 1, height: 48, background: C.panelBd, flexShrink: 0 }} />

            <div style={{ flexShrink: 0 }}>
                <div style={{ fontSize: 14, color: C.dim, marginBottom: 3 }}>Марка / Толщ.</div>
                <Seg value={zones[3]?.grade || '──'} width={52} />
                <div style={{ height: 4 }} />
                <Seg value={zones[3]?.thick ?? '─.─'} unit="мм" width={52} />
            </div>

            <div style={{ width: 1, height: 48, background: C.panelBd, flexShrink: 0 }} />

            <div style={{ flexShrink: 0 }}>
                <div style={{ fontSize: 18, color: C.dim, marginBottom: 3 }}>Параметры</div>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
                    {[
                        ['Скорость', speedDisplay, 'м/с'],
                        ['Уст.темп.', tempSetDisplay, '°C'],
                        ['Длина   ', lengthDisplay, 'м'],
                    ].map(([l, v, u]) => (
                        <div key={l} style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                            <span style={{ fontSize: 14, color: C.dim, minWidth: 62 }}>{l}</span>
                            <Seg value={v} unit={u} width={58} />
                        </div>
                    ))}
                </div>
            </div>

            <div style={{ marginLeft: 'auto', textAlign: 'right', flexShrink: 0 }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 5, justifyContent: 'flex-end', marginBottom: 2 }}>
                    <Led on={connected} color={C.green} size={8} />
                </div>
                <div style={{ fontSize: 24, color: C.accent, fontWeight: 700, letterSpacing: 3 }}>{fmt(time)}</div>
                <div style={{ fontSize: 14, color: C.dim }}>{new Date().toLocaleDateString('ru-RU')}</div>
            </div>
        </div>

        {/* ══ PROCESS PANEL ═════════════════════════════════════════════════ */}
        <div style={{
            background: C.panel, border: `2px solid ${C.panelBd}`,
            borderRadius: 6, padding: '8px 10px', marginBottom: 8,
            display: 'flex', flexDirection: 'column', gap: 5,
        }}>
            <div style={{ fontSize: 18, color: C.dim, letterSpacing: 1 }}>
                ТЕХНОЛОГИЧЕСКАЯ СХЕМА — ЛИНИЯ ЗАКАЛКИ
            </div>

            <div style={{ display: 'flex', gap: 5, flexWrap: 'wrap' }}>
                {[
                    { label: 'Вход. рольганг', sheet: svgEntry, color: C.accent },
                    { label: 'Зона 1', sheet: zones[0], color: '#f87171' },
                    { label: 'Зона 2', sheet: zones[1], color: '#fb923c' },
                    { label: 'Зона 3', sheet: zones[2], color: '#fbbf24' },
                    { label: 'Зона 4', sheet: zones[3], color: '#a3e635' },
                    { label: 'Закалка', sheet: qS, color: '#60a5fa' },
                    { label: 'Охлаждение', sheet: cS, color: '#34d399' },
                    { label: 'Выдача', sheet: liveData.output, color: '#a78bfa' },
                ].map(({ label, sheet, color }) => (
                    <div key={label} style={{
                        display: 'flex', alignItems: 'center', gap: 5,
                        background: '#0d1117', border: `1px solid ${C.panelBd}`,
                        borderRadius: 4, padding: '2px 7px', whiteSpace: 'nowrap',
                    }}>
                        <span style={{
                            width: 7, height: 7, borderRadius: '50%', flexShrink: 0,
                            display: 'inline-block',
                            background: sheet ? color : '#252a30',
                            boxShadow: sheet ? `0 0 4px ${color}` : 'none',
                        }} />
                        <span style={{ fontSize: 18, color: C.dim }}>{label}:</span>
                        <span style={{ fontSize: 18, color: sheet ? C.text : C.dim, fontFamily: 'monospace' }}>
                            {sheet ? `${sheet.melt}/${sheet.batch}/${sheet.pack}/${sheet.sheet}` : '—'}
                        </span>
                    </div>
                ))}
            </div>

            {/* ── SVG ───────────────────────────────────────────────────────── */}
            <svg width="100%" viewBox={`0 0 ${VW} ${VH}`} style={{ display: 'block' }}>
                <defs>
                    <style>{`
              @keyframes dashMove { to { stroke-dashoffset: -20; } }
              .flow-active { animation: dashMove 0.4s linear infinite; }
              .sheet-hover-target:hover { stroke-width: 2; opacity: 0.8; }
              @keyframes faultPulse {
                0%, 100% { opacity: 1; }
                50%      { opacity: 0.35; }
              }
              .valve-fault { animation: faultPulse 0.8s ease-in-out infinite; }
            `}</style>
                    {ZONE_FILL.map((_, i) => (
                        <linearGradient key={i} id={`gz${i}`} x1="0" y1="0" x2="0" y2="1">
                            <stop offset="0%" stopColor={ZONE_FILL[i]} stopOpacity={0.85} />
                            <stop offset="100%" stopColor={ZONE_FILL[i]} />
                        </linearGradient>
                    ))}
                    <linearGradient id="gq" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#1e3a5f" />
                        <stop offset="100%" stopColor="#1e40af" />
                    </linearGradient>
                    <marker id="arr" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto">
                        <path d="M0,0 L6,3 L0,6 Z" fill={C.accent} />
                    </marker>
                    <marker id="arrGreen" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto">
                        <path d="M0,0 L6,3 L0,6 Z" fill={C.green} />
                    </marker>
                </defs>

                <line x1={0} y1={rY + rH + 6} x2={VW} y2={rY + rH + 6}
                    stroke={C.panelBd} strokeWidth={1} />

                {/* ── INPUT CONVEYOR ── */}
                <text x={inX + inN * (rW + rGap) / 2} y={rY - 14} textAnchor="middle"
                    fill={C.dim} fontSize={9}>Вход. рольганг</text>
                <Rollers x={inX} y={rY} count={inN} w={rW} gap={rGap} h={rH} />
                {svgEntry && (
                    <g style={{ cursor: 'pointer' }} onClick={() => handleSheetClick('E1', svgEntry)}>
                        <SheetRect x={inX + 1} y={rY - 13} w={inN * (rW + rGap) - 4} h={13}
                            label={`${svgEntry.melt}/${svgEntry.batch}/${svgEntry.pack}/${svgEntry.sheet}`} color={C.accent} />
                        <rect x={inX - 1} y={rY - 15} width={inN * (rW + rGap) + 2} height={17}
                            rx={3} fill="transparent" stroke="#58a6ff" strokeWidth={0}
                            className="sheet-hover-target"
                        />
                    </g>
                )}
                {inputSheet && (
                    <g style={{ cursor: 'pointer' }} onClick={loadToFurnace}>
                        <rect x={inX} y={rY + rH + 12} width={inN * (rW + rGap)} height={16}
                            rx={3} fill="#145a32" stroke={C.green} strokeWidth={1} />
                        <text x={inX + inN * (rW + rGap) / 2} y={rY + rH + 23} textAnchor="middle"
                            fill={C.green} fontSize={9} fontWeight={700}>▶ В ПЕЧЬ</text>
                    </g>
                )}
                {!inputSheet && (
                    <text x={inX + inN * (rW + rGap) / 2} y={rY + rH + 22} textAnchor="middle"
                        fill="#333" fontSize={9}>▶ В ПЕЧЬ</text>
                )}

                <line
                    x1={inX + inN * (rW + rGap) + 2} y1={rY + rH / 2}
                    x2={fX - 4} y2={rY + rH / 2}
                    stroke={liveData.arrows.toFurnace ? C.green : C.accent}
                    strokeWidth={liveData.arrows.toFurnace ? 2.5 : 1.5}
                    strokeDasharray={liveData.arrows.toFurnace ? '6 4' : 'none'}
                    className={liveData.arrows.toFurnace ? 'flow-active' : ''}
                    markerEnd={liveData.arrows.toFurnace ? 'url(#arrGreen)' : 'url(#arr)'}
                />

                {/* ── 4 FURNACE ZONES ── */}
                {[0, 1, 2, 3].map(i => {
                    const zx = zoneX(i);
                    const sh = zones[i];
                    const moving = liveData.arrows.zones[i];
                    return (
                        <g key={i}>
                            <rect x={zx} y={rY - 42} width={zW} height={rH + 46} rx={3}
                                fill={`url(#gz${i})`}
                                stroke={sh ? ZONE_STROKE[i] : '#2a2a2a'}
                                strokeWidth={sh ? 2 : 1}
                                style={sh ? { filter: `drop-shadow(0 0 3px ${ZONE_STROKE[i]}55)` } : {}}
                            />
                            <text x={zx + zW / 2} y={rY - 30} textAnchor="middle"
                                fill={ZONE_LABEL[i]} fontSize={9} fontWeight={700}>ЗОНА {i + 1} НАГРЕВА</text>
                            <text x={zx + zW / 2} y={rY - 14} textAnchor="middle"
                                fill={ZONE_LABEL[i]} fontSize={13} fontWeight={700}>{realTemps[i]} °C</text>
                            {sh ? (
                                <g style={{ cursor: 'pointer' }} onClick={() => handleSheetClick(`F${i + 1}`, sh)}>
                                    <SheetRect
                                        x={zx + 5} y={rY - 1} w={zW - 10} h={rH - 4}
                                        label={`${sh.melt}/${sh.batch}/${sh.pack}/${sh.sheet}`}
                                        color={ZONE_FILL[i]}
                                    />
                                    <rect
                                        x={zx + 3} y={rY - 3} w={zW - 6} h={rH}
                                        rx={3} fill="transparent" stroke="#58a6ff" strokeWidth={0}
                                        className="sheet-hover-target"
                                    />
                                </g>
                            ) : (
                                <text x={zx + zW / 2} y={rY + rH / 2 + 4} textAnchor="middle"
                                    fill="#333" fontSize={9}>— пусто —</text>
                            )}
                            {i < 3 && (
                                <line
                                    x1={zx + zW + 1} y1={rY + rH / 2}
                                    x2={zoneX(i + 1) - 2} y2={rY + rH / 2}
                                    stroke={moving ? C.green : '#2a2a2a'}
                                    strokeWidth={moving ? 2 : 1}
                                    strokeDasharray={moving ? '5 3' : 'none'}
                                    className={moving ? 'flow-active' : ''}
                                    markerEnd={moving ? 'url(#arrGreen)' : ''}
                                />
                            )}
                        </g>
                    );
                })}

                <rect x={fX - 3} y={rY - 46} width={furnW + 6} height={rH + 54} rx={4}
                    fill="none" stroke="#3a3a3a" strokeWidth={1} strokeDasharray="5,3" />
                <text x={fX + furnW / 2} y={rY + rH + 26} textAnchor="middle"
                    fill="#3a3a3a" fontSize={9} letterSpacing={5}>П Е Ч Ь   З А К А Л К И</text>

                {(() => {
                    const moving = liveData.arrows.zones[3];
                    return (
                        <line
                            x1={fX + furnW + 4} y1={rY + rH / 2}
                            x2={qX - 4} y2={rY + rH / 2}
                            stroke={moving ? C.green : C.accent}
                            strokeWidth={moving ? 2.5 : 1.5}
                            strokeDasharray={moving ? '6 4' : 'none'}
                            className={moving ? 'flow-active' : ''}
                            markerEnd={moving ? 'url(#arrGreen)' : 'url(#arr)'}
                        />
                    );
                })()}

                {/* ── ЗАКАЛКА ── */}
                <rect x={qX} y={rY - 42} width={qW} height={rH + 46} rx={3}
                    fill="url(#gq)"
                    stroke={qS ? '#3b82f6' : '#1e2a3a'}
                    strokeWidth={qS ? 2 : 1}
                    style={qS ? { filter: 'drop-shadow(0 0 3px #3b82f655)' } : {}}
                />
                <text x={qX + qW / 2} y={rY - 30} textAnchor="middle"
                    fill="#93c5fd" fontSize={9} fontWeight={700}>ЗАКАЛКА</text>

                {/* ── LED КЛАПАНОВ ВЕРХ (9 шт) ── */}
                {topValves.map((st, i) => {
                    const cx = qX + 10 + i * ((qW - 20) / 8);
                    const cy = rY - 8;
                    return (
                        <g key={`qtv${i}`} className={st === 6 ? 'valve-fault' : ''}>
                            <ValveLed cx={cx} cy={cy} state={st} r={4} />
                        </g>
                    );
                })}

                {/* Сопла и лист */}
                <Nozzles9 x={qX + 5} y={rY - 4} active={running && !!qS} side="top" />
                <Nozzles9 x={qX + 5} y={rY + rH + 6} active={running && !!qS} side="bottom" />
                {qS
                    ? <SheetRect x={qX + 5} y={rY - 1} w={qW - 10} h={rH - 4}
                        label={`${qS.melt}/${qS.batch}/${qS.pack}/${qS.sheet}`} color="#1e3a8a" />
                    : <text x={qX + qW / 2} y={rY + rH / 2 + 4} textAnchor="middle"
                        fill="#252a50" fontSize={9}>— пусто —</text>
                }

                {/* ── LED КЛАПАНОВ НИЗ (9 шт) ── */}
                {bottomValves.map((st, i) => {
                    const cx = qX + 10 + i * ((qW - 20) / 8);
                    const cy = rY + rH + 8;
                    return (
                        <g key={`qbv${i}`} className={st === 6 ? 'valve-fault' : ''}>
                            <ValveLed cx={cx} cy={cy} state={st} r={4} />
                        </g>
                    );
                })}

                <text x={qX - 2} y={rY - 5} textAnchor="end" fill="#60a5fa" fontSize={7} fontWeight={700}>ВЕРХ</text>
                <text x={qX - 2} y={rY + rH + 11} textAnchor="end" fill="#60a5fa" fontSize={7} fontWeight={700}>НИЗ</text>

                <g style={{ cursor: 'default' }}>
                    <rect x={qX} y={rY + rH + 18} width={qW} height={14}
                        rx={3} fill="#1a2a4a" stroke="#3b82f6" strokeWidth={1} />
                    <text x={qX + qW / 2} y={rY + rH + 28} textAnchor="middle"
                        fill="#60a5fa" fontSize={8} fontWeight={700}>▶ В ЗАКАЛКУ</text>
                </g>

                <line x1={qX + qW + 4} y1={rY + rH / 2} x2={outX - 4} y2={rY + rH / 2}
                    stroke={C.accent} strokeWidth={1.5} markerEnd="url(#arr)" />

                {/* ── COOLING CONVEYOR (X1) ── */}
                <text x={outX + outN * (rW + rGap) / 2} y={rY - 14} textAnchor="middle"
                    fill={C.dim} fontSize={14}>Охлаждение</text>
                <Rollers x={outX} y={rY} count={outN} w={rW} gap={rGap} h={rH} />
                {cS && (
                    <g style={{ cursor: 'pointer' }} onClick={() => handleSheetClick('X1', cS)}>
                        <SheetRect x={outX + 1} y={rY - 13} w={outN * (rW + rGap) - 4} h={13}
                            label={`${cS.melt}/${cS.batch}/${cS.pack}/${cS.sheet}`} color="#0e4a6b" />
                    </g>
                )}

                <line
                    x1={outX + outN * (rW + rGap) + 4} y1={rY + rH / 2}
                    x2={finX - 10} y2={rY + rH / 2}
                    stroke={C.accent} strokeWidth={1.5} markerEnd="url(#arr)" />

                <text x={(finX + finN * (rW + rGap) / 2) - 10} y={rY - 14} textAnchor="middle"
                    fill={C.dim} fontSize={14}>Выдача</text>
                <Rollers x={finX - 10} y={rY} count={finN} w={rW} gap={rGap} h={rH} />
                {liveData.output && (
                    <g style={{ cursor: 'pointer' }} onClick={() => handleSheetClick('X2', liveData.output)}>
                        <SheetRect
                            x={finX - 10 + 1} y={rY - 13}
                            w={finN * (rW + rGap) - 4} h={13}
                            label={`${liveData.output.melt}/${liveData.output.batch}/${liveData.output.pack}/${liveData.output.sheet}`}
                            color="#2d1f4a"
                        />
                        {liveData.output.isDefect && (
                            <text x={finX - 10 + finN * (rW + rGap) / 2} y={rY + 14} textAnchor="middle"
                                fill={C.red} fontSize={10} fontWeight={700}>⚠ БРАК</text>
                        )}
                    </g>
                )}
            </svg>
        </div>

        {/* ══ PLANS + SHEETS ════════════════════════════════════════════════ */}
        <div style={{ display: 'flex', gap: 8 }}>
            <div style={{
                background: C.panel, border: `1px solid ${C.panelBd}`,
                borderRadius: 6, padding: 10, width: 265, flexShrink: 0,
            }}>
                <div style={{ fontSize: 14, color: C.accent, fontWeight: 700, letterSpacing: 1, marginBottom: 8 }}>
                    ПЛАНЫ ЗАКАЛКИ
                </div>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
                    {loading && (
                        <div style={{ color: C.dim, padding: 10, textAlign: 'center', fontSize: 14 }}>
                            Загрузка планов...
                        </div>
                    )}
                    {error && !loading && (
                        <div style={{ color: C.red, padding: 10, fontSize: 14, border: `1px solid ${C.red}`, borderRadius: 4 }}>
                            ⚠ {error}
                            <button onClick={fetchPlans} style={{
                                marginLeft: 8, background: 'transparent',
                                color: C.accent, border: `1px solid ${C.accent}`, borderRadius: 3,
                                padding: '1px 6px', cursor: 'pointer', fontSize: 14
                            }}>
                                Повторить
                            </button>
                        </div>
                    )}
                    {!loading && !error && plans.length === 0 && (
                        <div style={{ color: C.dim, padding: 10, textAlign: 'center', fontSize: 14 }}>
                            Нет доступных планов
                        </div>
                    )}
                    {plans.map(plan => {
                        const sel = selectedPlan?.id === plan.id;
                        const sc = statusColor(plan.status);
                        return (
                            <div key={plan.id}
                                onClick={() => handleSelectPlan(plan)}
                                style={{
                                    background: sel ? '#1a2f4a' : 'transparent',
                                    border: `1px solid ${sel ? C.accent : C.panelBd}`,
                                    borderLeft: `3px solid ${sel ? C.accent : 'transparent'}`,
                                    borderRadius: 4, padding: '7px 10px', cursor: 'pointer',
                                }}
                            >
                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 3 }}>
                                    <span style={{ fontWeight: 700, fontSize: 14 }}>{plan.planName}</span>
                                    <span style={{
                                        background: sc + '22', color: sc, border: `1px solid ${sc}`,
                                        borderRadius: 3, padding: '0 5px', fontSize: 14
                                    }}>{plan.status}</span>
                                </div>
                                <div style={{ display: 'flex', gap: 8, fontSize: 14, color: C.dim, flexWrap: 'wrap' }}>
                                    <span>📅 {plan.date}</span>
                                    <span>⏰ {plan.time}</span>
                                    <span>📋 {plan.sheetCount} л.</span>
                                    <span>{plan.furnace}</span>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            <div style={{
                background: C.panel, border: `1px solid ${C.panelBd}`,
                borderRadius: 6, padding: 10, flex: 1, minWidth: 0,
            }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
                    <div style={{ fontSize: 14, color: C.accent, fontWeight: 700, letterSpacing: 1 }}>
                        {sheetsLoading
                            ? 'Загрузка листов...'
                            : selectedPlan
                                ? `СОСТАВ: ${selectedPlan.planName} — ${planSheets.length} листов`
                                : 'ВЫБЕРИТЕ ПЛАН ИЗ СПИСКА'}
                    </div>
                    <button
                        onClick={addToConveyor}
                        disabled={!canAdd}
                        style={{
                            background: canAdd ? '#1a4731' : '#21262d',
                            color: canAdd ? C.green : C.dim,
                            border: `1px solid ${canAdd ? C.green : C.panelBd}`,
                            borderRadius: 4, padding: '6px 14px', fontSize: 14,
                            cursor: canAdd && !submitting ? 'pointer' : 'default',
                            fontFamily: 'monospace', fontWeight: 700,
                        }}
                    >
                        {submitting ? '⏳ Запись....' : '▶  Подать на входной рольганг'}</button>
                </div>

                {selectedPlan ? (
                    <div style={{ overflowX: 'auto' }}>
                        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 14 }}>
                            <thead>
                                <tr style={{ borderBottom: `1px solid ${C.panelBd}` }}>
                                    {['№', 'Плавка', 'Партия', 'Пачка', 'Лист', 'Марка', 'Толщ.', 'Ширина', 'Длина', 'Вес кг', 'Статус', 'Позиция', 'Действия'].map(h => (
                                        <th key={h} style={{
                                            padding: '3px 7px', color: C.dim, textAlign: 'left',
                                            fontWeight: 400, whiteSpace: 'nowrap'
                                        }}>{h}</th>
                                    ))}
                                </tr>
                            </thead>
                            <tbody>
                                {planSheets.map((row, i) => {
                                    const sel = selSheetId === row.id;
                                    const sc = statusColor(row.status);
                                    const canDelete = row.status === 'На рольганге' || row.status === 'В работе';

                                    return (
                                        <tr key={row.id}
                                            onClick={() => row.status === 'Ожидание' && setSelSheet(sel ? null : row.id)}
                                            style={{
                                                background: sel ? '#1a2f4a' : (i % 2 ? '#161b22' : 'transparent'),
                                                borderLeft: `3px solid ${sel ? C.accent : 'transparent'}`,
                                                cursor: row.status === 'Ожидание' ? 'pointer' : 'default',
                                                opacity: row.status === 'Завершён' ? 0.4 : 1,
                                            }}
                                        >
                                            <td style={{ padding: '3px 7px', color: C.dim }}>{i + 1}</td>
                                            <td style={{ padding: '3px 7px', fontFamily: 'monospace' }}>{row.melt}</td>
                                            <td style={{ padding: '3px 7px', fontFamily: 'monospace' }}>{row.batch}</td>
                                            <td style={{ padding: '3px 7px', fontFamily: 'monospace' }}>{row.pack}</td>
                                            <td style={{ padding: '3px 7px', fontFamily: 'monospace', color: C.accent, fontWeight: 700 }}>{row.sheet}</td>
                                            <td style={{ padding: '3px 7px', color: C.yellow }}>{row.grade}</td>
                                            <td style={{ padding: '3px 7px', textAlign: 'left' }}>{row.thick}</td>
                                            <td style={{ padding: '3px 7px', textAlign: 'left' }}>{row.width}</td>
                                            <td style={{ padding: '3px 7px', textAlign: 'left' }}>{row.len}</td>
                                            <td style={{ padding: '3px 7px', textAlign: 'left', color: C.dim }}>{row.wt}</td>
                                            <td style={{ padding: '3px 7px' }}>
                                                <span style={{
                                                    background: sc + '22', color: sc, border: `1px solid ${sc}`,
                                                    borderRadius: 3, padding: '0 5px', fontSize: 14, whiteSpace: 'nowrap'
                                                }}>
                                                    {row.status}
                                                </span>
                                            </td>
                                            <td style={{ padding: '3px 7px', color: row.loc ? C.text : C.dim }}>
                                                {row.loc || '—'}
                                            </td>
                                            <td style={{ padding: '3px 7px' }}>
                                                {canDelete && row.loc && (
                                                    <button
                                                        onClick={(e) => {
                                                            e.stopPropagation();
                                                            // ИСПРАВЛЕНО: используем getZoneTag для надежного определения зоны
                                                            const zoneTag = getZoneTag(row.loc);
                                                            if (zoneTag) {
                                                                deleteFromZone(row.id, zoneTag);
                                                            }
                                                        }}
                                                        style={{
                                                            background: '#3d1f1f',
                                                            color: C.red,
                                                            border: `1px solid ${C.red}`,
                                                            borderRadius: 3,
                                                            padding: '2px 8px',
                                                            fontSize: 12,
                                                            cursor: 'pointer',
                                                            fontWeight: 700,
                                                        }}
                                                    >
                                                        Удалить
                                                    </button>
                                                )}
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>
                ) : (
                    <div style={{ color: C.dim, padding: 20, textAlign: 'center' }}>
                        Выберите план закалки из списка слева
                    </div>
                )}
            </div>
        </div>

        {/* ══ DEFECT MODAL ═════════════════════════════════════════════════ */}
        {defectModal.open && (
            <div style={{
                position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
                background: 'rgba(0,0,0,0.75)', zIndex: 1000,
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                padding: 20,
            }} onClick={closeDefectModal}>
                <div
                    style={{
                        background: C.panel, border: `2px solid ${C.red}`,
                        borderRadius: 8, padding: '20px 25px',
                        minWidth: 480, maxWidth: 600, color: C.text,
                        boxShadow: `0 0 30px ${C.red}55`,
                    }}
                    onClick={e => e.stopPropagation()}
                >
                    <div style={{
                        display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                        marginBottom: 15, paddingBottom: 10, borderBottom: `1px solid ${C.panelBd}`,
                    }}>
                        <div style={{ fontSize: 18, fontWeight: 700, color: C.red }}>
                            🚨 Установка статуса БРАК
                        </div>
                        <button onClick={closeDefectModal} style={{
                            background: 'transparent', border: 'none', color: C.dim,
                            fontSize: 24, cursor: 'pointer', padding: '0 8px',
                        }}>×</button>
                    </div>

                    {defectModal.loading && !defectModal.sheet ? (
                        <div style={{ padding: 20, textAlign: 'center', color: C.dim }}>
                            Загрузка данных листа...
                        </div>
                    ) : defectModal.sheet ? (
                        <>
                            <div style={{
                                background: C.bg, padding: 12, borderRadius: 4,
                                marginBottom: 15, fontFamily: 'monospace',
                            }}>
                                <div style={{ display: 'grid', gridTemplateColumns: '120px 1fr', gap: '6px 12px', fontSize: 14 }}>
                                    <span style={{ color: C.dim }}>MatId:</span>
                                    <span style={{ color: C.accent, fontWeight: 700 }}>{defectModal.sheet.matId}</span>
                                    <span style={{ color: C.dim }}>Плавка:</span>
                                    <span>{defectModal.sheet.meltNumber}</span>
                                    <span style={{ color: C.dim }}>Партия:</span>
                                    <span>{defectModal.sheet.batchNumber}</span>
                                    <span style={{ color: C.dim }}>Пачка:</span>
                                    <span>{defectModal.sheet.packNumber}</span>
                                    <span style={{ color: C.dim }}>Лист:</span>
                                    <span style={{ color: C.accent, fontWeight: 700 }}>{defectModal.sheet.sheetNumber}</span>
                                    <span style={{ color: C.dim }}>Зона обнаружения:</span>
                                    <span style={{ color: C.yellow, fontWeight: 700 }}>{defectModal.detectedZone}</span>
                                </div>
                            </div>

                            <div style={{ marginBottom: 15 }}>
                                <label style={{ display: 'block', fontSize: 13, color: C.dim, marginBottom: 5 }}>
                                    Тип дефекта:
                                </label>
                                <select
                                    value={defectModal.defectTypeId || ''}
                                    onChange={e => setDefectModal(prev => ({ ...prev, defectTypeId: parseInt(e.target.value) || null }))}
                                    style={{
                                        width: '100%', background: C.bg, color: C.text,
                                        border: `1px solid ${C.panelBd}`, borderRadius: 4,
                                        padding: 8, fontSize: 14,
                                    }}
                                >
                                    <option value="">-- Выберите тип --</option>
                                    {defectTypes.map(dt => (
                                        <option key={dt.id} value={dt.id}>{dt.name}</option>
                                    ))}
                                </select>
                            </div>

                            <div style={{ marginBottom: 15 }}>
                                <label style={{ display: 'block', fontSize: 13, color: C.dim, marginBottom: 5 }}>
                                    Причина брака:
                                </label>
                                <textarea
                                    value={defectModal.reason}
                                    onChange={e => setDefectModal(prev => ({ ...prev, reason: e.target.value }))}
                                    placeholder="Опишите причину брака..."
                                    rows={3}
                                    style={{
                                        width: '100%', background: C.bg, color: C.text,
                                        border: `1px solid ${C.panelBd}`, borderRadius: 4,
                                        padding: 8, fontSize: 14, fontFamily: 'inherit',
                                        resize: 'vertical', boxSizing: 'border-box',
                                    }}
                                />
                            </div>

                            {defectModal.error && (
                                <div style={{
                                    background: '#f8514933', border: `1px solid ${C.red}`,
                                    padding: 10, borderRadius: 4, marginBottom: 15,
                                    color: C.red, fontSize: 13,
                                }}>
                                    ⚠ {defectModal.error}
                                </div>
                            )}

                            <div style={{ display: 'flex', gap: 10, justifyContent: 'flex-end' }}>
                                <button onClick={closeDefectModal} style={{
                                    background: 'transparent', color: C.dim,
                                    border: `1px solid ${C.panelBd}`, borderRadius: 4,
                                    padding: '8px 16px', cursor: 'pointer', fontSize: 14,
                                }}>
                                    Отмена
                                </button>
                                <button
                                    onClick={markAsDefect}
                                    disabled={defectModal.loading}
                                    style={{
                                        background: C.red, color: '#fff',
                                        border: 'none', borderRadius: 4,
                                        padding: '8px 16px', cursor: 'pointer', fontSize: 14,
                                        fontWeight: 700, opacity: defectModal.loading ? 0.6 : 1,
                                    }}
                                >
                                    {defectModal.loading ? '⏳ Установка...' : '🚨 Установить БРАК'}
                                </button>
                            </div>
                        </>
                    ) : (
                        <div style={{ padding: 20, textAlign: 'center', color: C.red }}>
                            {defectModal.error || 'Лист не найден'}
                        </div>
                    )}
                </div>
            </div>
        )}
    </div>
);
}